head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnEditFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 editFormat 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 editFormat 속성을 설정하려는 Body Column 의 ID 를 설정할 수 있어야 합니다.",
    ]
}



// columnInfo(Column ID) 별 적용할 editFormat 마스크 (ID 호출 검증용)
scwin.colEditFormatMap = {
    "dDate":   "####/##/##",
    "dHide":   "##-##",
    "dCustom": "####/##/##",
    "dText":   "AAA",
    "dPhone":  "###-####"
};



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : text/text(숨김)/custom/text/text Column 구성. setColumnEditFormat 을 Column ID 로 호출.
//  setColumnEditFormat 은 inputType='text'(또는 'input') 인 Column 에서만 동작 -> dCustom(custom) 은 미동작
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column(숨김 포함) dDate(text·동작) / dHide(text·숨김·동작) / dCustom(custom·미동작) / dText(text·동작) / dPhone(text·동작), 데이터 3행. columnInfo 파라미터를 인덱스가 아닌 Column ID 문자열로 호출.\n[절차] columnInfo(Column ID) 선택 -> setColumnEditFormat 실행. inputType=text 셀 더블클릭 편집 시 editFormat 마스크로 입력이 제한됨.\n[확인] Column ID 로 지목되어 inputType=text 컬럼만 동작 - dDate=####/##/## (20250115->2025/01/15), dPhone=###-#### (1234567->123-4567). dCustom(custom)은 미동작(반환 false)."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="dDate" name="dDate" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dHide" name="dHide" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dCustom" name="dCustom" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dText" name="dText" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dPhone" name="dPhone" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "dDate": "20250115", "dHide": "0115", "dCustom": "20250115", "dText": "ABC", "dPhone": "1234567" },
        { "dDate": "20251231", "dHide": "1231", "dCustom": "20251231", "dText": "XYZ", "dPhone": "9876543" },
        { "dDate": "20250707", "dHide": "0707", "dCustom": "20250707", "dText": "DEF", "dPhone": "1112222" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (text/text(숨김)/custom/text/text Column. body 컬럼 id 는 dataList 컬럼 id 와 동일해야 바인딩)
    //  columnInfo 파라미터를 (인덱스가 아닌) Column ID 문자열로 호출 -> dDate(동작)/dHide(숨김,동작)/dCustom(custom,미동작)/dText(동작)/dPhone(동작)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:620px;height:220px;" editable="true" ev:onbeforeedit="scwin.target1_onbeforeedit" ev:onafteredit="scwin.target1_onafteredit">';
    strTarget += '<w2:caption style="" id="caption1" value="setColumnEditFormat 테스트 그리드 (Column ID 호출)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="140" inputType="text" id="h0" value="dDate(text)"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="h1" value="dHide(text/숨김)"></w2:column>';
    strTarget += '<w2:column width="140" inputType="text" id="h2" value="dCustom(custom)"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="h3" value="dText(text)"></w2:column>';
    strTarget += '<w2:column width="130" inputType="text" id="h4" value="dPhone(text)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    // dDate : text -> Column ID 호출 동작 대상 (editFormat ####/##/##)
    strTarget += '<w2:column width="140" inputType="text" dataType="text" id="dDate" dataList="dDate"></w2:column>';
    // dHide : text 숨김(setColumnVisible(1,false)) -> Column ID 로는 숨김 Column 도 지목 가능
    strTarget += '<w2:column width="110" inputType="text" dataType="text" id="dHide" dataList="dHide"></w2:column>';
    // dCustom : custom -> 전제 미충족(inputType=custom) -> 미동작(setColumnEditFormat 반환 false)
    strTarget += '<w2:column width="140" inputType="custom" dataType="text" id="dCustom" dataList="dCustom"></w2:column>';
    // dText : text -> Column ID 호출 동작 대상 (editFormat AAA, 대문자 알파벳)
    strTarget += '<w2:column width="100" inputType="text" dataType="text" id="dText" dataList="dText"></w2:column>';
    // dPhone : text -> Column ID 'dPhone' 호출 시 ###-#### 마스크 정상 적용
    strTarget += '<w2:column width="130" inputType="text" dataType="text" id="dPhone" dataList="dPhone"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // dHide(인덱스 1) 숨김 -> Column ID 로 숨김 Column 도 지목 가능함을 확인
    target1.setColumnVisible(1, false);
}



// [실행] setColumnEditFormat : columnInfo 파라미터에 (인덱스가 아닌) Column ID 문자열을 전달하여 editFormat 을 설정한다.
//  - 설정 직후 getColumnEditFormat(Column ID) 로 editFormat 속성값을 확인하고, 셀 표시값이 마스크대로 변경됨을 확인
scwin.btn_setColumnEditFormat_onclick = function () {
    // columnInfo 파라미터 : Column ID 문자열
    let colID = par_columnInfo.getValue();
    let editFormat = scwin.colEditFormatMap[colID];

    let colIndex = target1.getColumnIndex(colID);
    let beforeArr = scwin.collectColText(colIndex);

    // columnInfo 파라미터에 Column ID 문자열을 전달하여 호출
    let ret = target1.setColumnEditFormat(colID, editFormat);

    // 쌍이 되는 get 메소드(getColumnEditFormat)도 Column ID 로 호출하여 설정값 확인
    let getFmt = target1.getColumnEditFormat(colID);
    let afterArr = scwin.collectColText(colIndex);

    let msg = "setColumnEditFormat('" + colID + "', '" + editFormat + "') 반환값=" + ret;
    msg += "\n[getColumnEditFormat('" + colID + "')] " + getFmt;
    msg += "\n[표시값] " + beforeArr.join(', ') + "  ->  " + afterArr.join(', ');
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}

// 해당 Column 의 모든 Row 화면 표시값(td.textContent) 수집
scwin.collectColText = function (colIndex) {
    let cnt = dlt_bind.getRowCount();
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + colIndex + "']");
        arr.push(td ? td.textContent.trim() : '');
    }
    return arr;
}

// [이벤트] 셀을 직접 편집 -> 포커스 아웃(onafteredit) 하는 실제 인터랙션마다 편집값/표시값 자동 출력
scwin.target1_onbeforeedit = function (row, col, value) {
    scwin._editValue = value;   // 편집 입력창 표시값 보관(참고용)
};
scwin.target1_onafteredit = function (row, col, value) {
    let colID = target1.getColumnID(col);
    // onafteredit 의 value 는 마스크 미적용 원본값이므로, 편집 입력창(G_...target1__<colID>) 의 마스크 적용값을 캡처
    let editor = document.querySelector("input[id^='G_'][id$='target1__" + colID + "']");
    let editVal = editor ? editor.value : value;
    let td = document.querySelector("td[id*='target1_cell_" + row + "_" + col + "']");
    let dispVal = td ? td.textContent.trim() : '';
    let msg = "편집->포커스아웃 [" + colID + "] (" + row + "," + col + ")";
    msg += "\n[편집값] " + editVal;
    msg += "\n[표시값] " + dispVal;
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
};
